inline float evalBp (const Curve& c, float u)
{
    u -= std::floor (u);
    const Bp* p = c.p; int lo = 0, hi = c.n - 1;
    while (hi - lo > 1) { const int m = (lo + hi) / 2; if (p[m].u <= u) lo = m; else hi = m; }
    const float d = p[hi].u - p[lo].u;
    return d <= 0.0f ? p[hi].v : p[lo].v + (p[hi].v - p[lo].v) * (u - p[lo].u) / d;
}
inline float valueNoise (float u, uint32_t seed)
{
    const float x = (u - std::floor (u)) * 256.0f; const int i = (int) x; const float f = x - (float) i;
    auto h = [seed] (int k) { uint32_t v = (uint32_t) (k & 255) * 2654435761u ^ seed * 40503u; v ^= v >> 13; v *= 0x5bd1e995u; v ^= v >> 15; return (float) (v & 0xffff) / 32767.5f - 1.0f; };
    return h (i) + (h (i + 1) - h (i)) * f;
}
// the LFO menu (bipolar except the "uni" tables, which run 0..1)
inline float lfo (int shape, float u, uint32_t seed = 0x51u)
{
    u -= std::floor (u);
    switch (shape)
    {
        case 0: return std::sin (6.2831853f * u);
        case 1: return 1.0f - 2.0f * u;
        case 2: return u < 0.5f ? 1.0f : -1.0f;
        case 3: return u < 0.5f ? 4.0f * u - 1.0f : 3.0f - 4.0f * u;
        default: break;
    }
    const int t = std::clamp (shape - 4, 0, 30);
    if (t == 18) return valueNoise (u, seed);
    return evalBp (lfoTables[t], u);
}
// the performer menu (unipolar, 0..1)
inline float perf (int shape, float u) { return evalBp (perfTables[std::clamp (shape, 0, 15)], u); }
