// the envelope sustain-stage shapes (0..1 over the stage; not periodic)
inline float env (int shape, float u) { const auto& c = envTables[std::clamp (shape, 0, 21)]; u = std::clamp (u, 0.0f, 1.0f); const Bp* p = c.p; int i = 0; while (i < c.n - 2 && p[i + 1].u < u) ++i; const float d = p[i + 1].u - p[i].u; return d <= 0.0f ? p[i + 1].v : p[i].v + (p[i + 1].v - p[i].v) * (u - p[i].u) / d; }
